const keyTakeawayEnd = rawSourceContent.search(/\n\s*Brain Health/);
const keyTakeawayLabels = rawSourceContent
  .slice(0, keyTakeawayEnd > 0 ? keyTakeawayEnd : 0)
  .split("\n")
